pub fn find_median(a: &[i32], b: &[i32]) -> i32 {
    // assume a.len() == b.len() > 0
    let n = a.len();
    if n % 2 == 1 {
        // odd: return the middle element of a
        a[n / 2]
    } else {
        // even: floor((a[n/2 - 1] + b[0]) / 2)
        let x = a[n / 2 - 1] as i64;
        let y = b[0] as i64;
        // div_euclid with positive divisor 2 gives the mathematical floor for negative sums
        (x + y).div_euclid(2) as i32
    }
}

